/bin/bash -lc "python3 - <<'PY'
import json,re,subprocess
p=json.load(open('packet.json'))
groups={}
for x in p['items']:
 if x['question'].startswith('Change request'):
  doc=re.search(r'R3-\\d+',x['question']).group()
  q=\"MATCH (t:Tdoc {tdocNumber: '\"+doc+\"'})-[:BELONGS_TO_CR_PACK]->(p:CRPack) MATCH (r:Resolution {resolutionScope: 'document_disposition'})-[:HAS_DISPOSITION]->(d:DecisionDisposition {evidenceStatus: 'source_verified'})-[:DISPOSITION_TARGET]->(t) MATCH (r)-[:MADE_AT]->(m:Meeting {workingGroup: 'RAN3'}) RETURN DISTINCT d.dispositionCode AS disposition, m.meetingNumber AS wg_meeting, p.crPackId AS cr_pack, p.tsgMeeting AS tsg_meeting\"
  result=subprocess.run(['python3','query_graph.py',q],capture_output=True,text=True)
  try:
   data=json.loads(result.stdout)
   print(json.dumps({'id':x['id'],'count':data.get('rowCount'),'columns':data.get('columns'),'truncated':data.get('truncated'),'error':data.get('error') or (result.stderr if result.returncode else None)}))
  except Exception:
   print(json.dumps({'id':x['id'],'raw':result.stdout,'stderr':result.stderr}))
PY"

